return [{
  json: {
    mensaje: 'Por ahora solo puedo leer mensajes de texto — ¿me escribes tu síntoma?'
  }
}];

// Evalúa si la búsqueda en Notion encontró una especialidad válida
// Y extrae el plan (Premium/Básico) que el paciente menciona en su propio mensaje.
// No hay pre-registro de paciente: el plan viene siempre del texto.
const items = $input.all();
const huboError = items.some(item => item.json.error);
const especialidadEncontrada = !huboError && items.length > 0;

let especialidad = null;
if (especialidadEncontrada) {
  const props = items[0].json.properties || {};
  especialidad = props.Especialidad?.select?.name
    || props.Especialidad?.rich_text?.[0]?.plain_text
    || null;
}

const sintomaOriginal = $('Telegram Trigger').item.json.message.text;

// Normaliza (minúsculas, sin acentos) para detectar 'premium' / 'basico' sin importar mayúsculas o tildes.
const textoNormalizado = (sintomaOriginal || '')
  .toLowerCase()
  .normalize('NFD')
  .replace(/[\u0300-\u036f]/g, '');

let plan = null;
if (/\bpremium\b/.test(textoNormalizado)) {
  plan = 'Premium';
} else if (/\bbasico\b/.test(textoNormalizado)) {
  plan = 'Básico';
}

const especialidadFinal = especialidad !== null;
const planEncontrado = plan !== null;

const faltantes = [];
if (!especialidadFinal) faltantes.push('especialidad');
if (!planEncontrado) faltantes.push('plan');

return [{
  json: {
    especialidadEncontrada: especialidadFinal,
    especialidad,
    planEncontrado,
    plan,
    faltantes,
    sintomaOriginal,
    paso2Error: huboError
  }
}];

// Cálculo determinístico del copago y comparación de hospitales.
// Este cálculo se hace EXCLUSIVAMENTE aquí, en JavaScript puro.
// NUNCA se le pide a Groq (ni a ningún LLM) que calcule o compare montos:
// un LLM no es confiable para aritmética con dinero real.

// Ambos nodos Notion tienen alwaysOutputData=true: si no hubo match,
// igual entregan 1 item con json:{} (sin 'properties') solo para que
// el Merge/este Function se disparen. Por eso se filtran esos items
// vacíos antes de contar/calcular, en vez de confiar en el length crudo.
const hospitalesItems = $('Notion - Obtener Hospitales de la Red').all()
  .filter(item => item.json && item.json.properties);
const planItem = $('Notion - Obtener Regla del Plan').first();

const planProps = planItem?.json?.properties || {};
const tipoDeRegla = planProps['Tipo de regla']?.select?.name
  ?? planProps['Tipo de regla']?.rich_text?.[0]?.plain_text
  ?? null;
const valorRegla = planProps['Valor']?.number;

// Dato incompleto: NUNCA se asume un valor por defecto para la regla del plan.
// Se lanza un error explícito, que el IF de más abajo detecta y convierte
// en el mensaje de espera — no se calcula con un supuesto inventado.
if (typeof valorRegla !== 'number') {
  throw new Error('No se encontró la regla del plan (Plan + Especialidad) en Notion. Dato incompleto, no se puede calcular el copago sin inventar un valor.');
}

if (hospitalesItems.length === 0) {
  throw new Error('No se encontraron hospitales para la especialidad encontrada.');
}

const hospitales = hospitalesItems.map(item => {
  const props = item.json.properties || {};
  const costoBase = props['Costo base']?.number ?? 0;
  const nombre = props['Hospital']?.title?.[0]?.plain_text ?? 'Hospital sin nombre';
  const copago = costoBase * valorRegla;
  return { nombre, costoBase, copago };
});

const montos = hospitales.map(h => h.copago);
const copagoMinimo = Math.min(...montos);
const hospitalRecomendado = hospitales.find(h => h.copago === copagoMinimo);

return [{
  json: {
    especialidad: $('Function - Evaluar Coincidencia').first().json.especialidad,
    plan: $('Function - Evaluar Coincidencia').first().json.plan,
    tipoDeRegla,
    valorRegla,
    hospitales,
    hospitalRecomendado,
    copagoFinal: copagoMinimo
  }
}];

return [{
  json: {
    mensaje: 'Dame un momento, estoy verificando tu cobertura 🙏. Si no recibes una respuesta en los próximos minutos, intenta escribirme de nuevo.'
  }
}];

const contenido = $json.choices?.[0]?.message?.content;

return [{
  json: {
    mensaje: contenido || 'No pude generar una respuesta en este momento, por favor intenta de nuevo.'
  }
}];

const ejecucion = $json.execution || {};
const workflow = $json.workflow || {};

return [{
  json: {
    mensaje: `⚠️ Copayo tuvo un fallo crítico.\nWorkflow: ${workflow.name || 'desconocido'}\nÚltimo nodo ejecutado: ${ejecucion.lastNodeExecuted || 'desconocido'}\nRevisar la ejecución en n8n.`
  }
}];
